args.command:
node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [
  ['-1', -1, false], ['0', 0, true], ['3', 3, true], ['4', 4, false],
  ['string "3"', '3', false], ['null', null, false], ['NaN', NaN, false], ['fraction 1.5', 1.5, false],
  ['undefined', undefined, false], ['Infinity', Infinity, false], ['-Infinity', -Infinity, false]
];
let ok = true;
for (const [label, value, expected] of cases) {
  const actual = permit(value);
  console.log(`${label}: ${actual} (expected ${expected})`);
  if (actual !== expected) ok = false;
}
if (!ok) process.exit(1);
EOF
